CREATE TABLE IF NOT EXISTS "filestat"("timestamp" TIMESTAMP,"boot" TEXT,"file" TEXT,"modification_time" INT,"exists" INT,"size_bytes" INT);
CREATE TABLE IF NOT EXISTS "disk"("timestamp" TIMESTAMP,"boot" TEXT,"device" TEXT,"fstype" TEXT,"label" TEXT,"mode" TEXT,"path" TEXT,"total" INT UNSIGNED,"used" INT UNSIGNED);
CREATE TABLE IF NOT EXISTS "pressure"("timestamp" TIMESTAMP,"boot" TEXT,"resource" TEXT,"type" TEXT,"total" INT UNSIGNED);
CREATE TABLE IF NOT EXISTS "net"("timestamp" TIMESTAMP,"boot" TEXT,"interface" TEXT,"bytes_recv" INT UNSIGNED,"bytes_sent" INT UNSIGNED);
CREATE TABLE IF NOT EXISTS "mem"("timestamp" TIMESTAMP,"boot" TEXT,"available" INT UNSIGNED,"total" INT UNSIGNED,"used" INT UNSIGNED);
CREATE TABLE IF NOT EXISTS "game_status"("timestamp" TIMESTAMP,"boot" TEXT,"closes_1011" DOUBLE,"rate_limited_messages" DOUBLE,"closes_1008" DOUBLE,"closes_1000" DOUBLE,"active_games" DOUBLE,"pending_games" DOUBLE,"timeouts_turn" DOUBLE,"messages_in" DOUBLE,"handling_seconds" DOUBLE,"handled_messages" DOUBLE,"closes_4004" DOUBLE,"closes_4001" DOUBLE,"loop_lag_max_ms" DOUBLE,"connections" DOUBLE,"timeouts_meld" DOUBLE,"ai_replacements" DOUBLE,"bytes_out" DOUBLE,"connections_accepted" DOUBLE,"bytes_in" DOUBLE,"malformed_messages" DOUBLE,"timeouts_round_advance" DOUBLE,"reconnects" DOUBLE,"closes_4002" DOUBLE,"messages_out" DOUBLE,"started_at" DOUBLE,"resyncs" DOUBLE,"takeovers" DOUBLE);
CREATE TABLE IF NOT EXISTS "cgroup"("timestamp" TIMESTAMP,"boot" TEXT,"path" TEXT,"memory_current" INT,"memory_events_oom_kill" INT,"cpu_stat_usage_usec" INT);
CREATE TABLE IF NOT EXISTS "traefik"("timestamp" TIMESTAMP,"boot" TEXT,"code" TEXT,"method" TEXT,"protocol" TEXT,"router" TEXT,"traefik_router_request_duration_seconds_sum" DOUBLE,"traefik_router_request_duration_seconds_count" DOUBLE);
CREATE TABLE IF NOT EXISTS "filecount"("timestamp" TIMESTAMP,"boot" TEXT,"directory" TEXT,"size_bytes" INT);
CREATE TABLE IF NOT EXISTS "cpu"("timestamp" TIMESTAMP,"boot" TEXT,"cpu" TEXT,"time_steal" DOUBLE,"time_guest" DOUBLE,"time_system" DOUBLE,"time_idle" DOUBLE,"time_iowait" DOUBLE,"time_irq" DOUBLE,"time_softirq" DOUBLE,"time_guest_nice" DOUBLE,"time_user" DOUBLE,"time_nice" DOUBLE);
CREATE INDEX "idx_filestat_timestamp" ON "filestat" (timestamp);
CREATE INDEX "idx_disk_timestamp" ON "disk" (timestamp);
CREATE INDEX "idx_pressure_timestamp" ON "pressure" (timestamp);
CREATE INDEX "idx_net_timestamp" ON "net" (timestamp);
CREATE INDEX "idx_mem_timestamp" ON "mem" (timestamp);
CREATE INDEX "idx_game_status_timestamp" ON "game_status" (timestamp);
CREATE INDEX "idx_cgroup_timestamp" ON "cgroup" (timestamp);
CREATE INDEX "idx_traefik_timestamp" ON "traefik" (timestamp);
CREATE INDEX "idx_filecount_timestamp" ON "filecount" (timestamp);
CREATE INDEX "idx_cpu_timestamp" ON "cpu" (timestamp);
